i did look into it a little after the last reply since at that point it seemed like a clear conflict.
something in mog's plugin seems to delete the _battler from the actor sprites, which causes yanfly's battle engine to skip over them when determining if an animation is playing and renders it unable to wait for animations on battlers. i havent really had the time to try to fully resolve it
Edit:
save this as a .js file and load it below the hud plugin
@Jasanimation
Spoiler
Code:
(() => {
  Scene_Battle.prototype.actorSprites = function() {
      return this._spriteset._actorSprites;
  };
  Scene_Battle.prototype.updateActors = function() {
      var members = $gameParty.battleMembers();
      for (var i = 0; i < this.actorSprites().length; i++) {
          this.actorSprites()[i].setBattler(members[i]);
      }
  };

  Scene_Battle.prototype.updateBattleHud = function() {
    if ($gameTemp._forceCreateBattleHud) {this.forceCreateBattleHud()};
    if ($gameTemp._forceRemoveBattleHud) {this.forceRemoveBattleHud()};  
    if (this._screen_layout) {this.updateBattleHudVisible()};
    this.updateWindowSlideEffect()
    this.updateLayoutWindow();
    if (this.actorSprites()) {this.updateActors()};
  };

  Scene_Base.prototype.createActorsF = function() {
    if (this.actorSprites()) {
      for (var i = 0; i < this.actorSprites().length; i++) {
          this._hudField.removeChild(this.actorSprites()[i]);
      };
    };
      if (this._spriteset)
        this._spriteset._actorSprites = [];

      for (var i = 0; i < $gameParty.maxBattleMembers(); i++) {
          this.actorSprites()[i] = new Sprite_Actor();
      this.actorSprites()[i].mz = 110;
          this._hudField.addChild(this.actorSprites()[i]);
      };
  };
})();

